import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,p})=>{let type=p[0];for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++){g.box(x*.63,y*.52,0,.25,.2,.22,C.green);if(type===2)g.box(x*.63,y*.52,0,.15,.1,.13,C.gold);if(type===1)for(let a of[-1,1])for(let d of[-1,1])g.sphere(x*.63+a*.21,y*.52+d*.16,0,.055,C.gold);if(type!==2)g.sphere(x*.63,y*.52,0,.04,C.blue)}return[{label:b('Tissue','ऊतक'),value:[b('Parenchyma','पैरेन्काइमा'),b('Collenchyma','कॉलेन्काइमा'),b('Sclerenchyma','स्क्लेरेन्काइमा')][type]},{label:b('Wall pattern','भित्ति की बनावट'),value:[b('Thin walls','पतली भित्तियाँ'),b('Uneven corner thickening','कोनों पर असमान मोटाई'),b('Thick lignified walls','मोटी लिग्निनयुक्त भित्तियाँ')][type]}];};
